// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1 wei, 1 ether);

        // adversarial re-entrant counterparty
        ReentrantAttacker attacker = new ReentrantAttacker(c);

        // fund the attacker and let it deposit
        vm.deal(address(attacker), amount);
        attacker.deposit(amount);
        assertEq(c.getBalance(address(attacker)), amount);

        // attacker triggers withdrawBalance, which re-enters withdrawBalance in its receive()
        bool ok;
        try attacker.triggerWithdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a re-entrant withdrawal attempt is always rejected by the guard:
        // the whole withdrawal reverts, so the caller's recorded balance is intact.
        // The mutant (guard flag never set) lets the re-entrant withdrawal succeed,
        // zeroing the caller's balance, breaking the rule.
        assertTrue(!ok && c.getBalance(address(attacker)) != 0);
    }
}

contract ReentrantAttacker {
    C immutable c;
    bool attacked;

    constructor(C c_) { c = c_; }

    function deposit(uint256 amount) external payable {
        c.addToBalance{value: amount}();
    }

    function triggerWithdraw() external {
        c.withdrawBalance();
    }

    receive() external payable {
        if (!attacked) {
            attacked = true;
            c.withdrawBalance();
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    receive() external payable {}
    function check(uint256 amount) public {
        require(address(this).balance >= amount);
        c.addToBalance{value: amount}();
        assert(c.getBalance(address(this)) == amount);
    }
}

